/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: deletionDependencies, previewKey
 *   Constants: trackId, replacementId, stalePendingId, nextReplacementId, originalKey, replacementKey,
 *              stalePendingKey, nextReplacementKey, uploadFile, videoUploadFile
 * Tests
 *   - Soundtrack deletion retains metadata until storage and reference cleanup finish
 *   - Soundtrack deletion removes every recorded video key before metadata finalization
 *   - reference cleanup failure remains recorded and retryable without deleting metadata
 *   - cover-art record finalization failure is reported after Soundtrack deletion
 *   - a committed Soundtrack delete is confirmed after its database response is lost
 *   - Soundtrack deletion retains lifecycle evidence when the stored S3 key is missing or invalid
 *   - Soundtrack deletion stops before object cleanup when cover-art evidence is missing
 *   - Soundtrack deletion performs no cleanup when its lifecycle fence loses the race
 *   - audit-triggered deletion stops when a replacement changed the expected S3 key
 *   - audio object keys bind legacy and versioned storage to one Soundtrack identity
 *   - cross-kind replacement keeps the new Video active while failed Audio cleanup remains retryable
 *   - audio upload cannot cross a deletion fence
 *   - audio upload retries recorded failed-object cleanup before reserving a replacement
 *   - audio replacement uploads a versioned key, attaches it, then deletes the previous object
 *   - audio replacement checks final attachment and removes an unattached uploaded object
 *   - definite upload rejection releases its reservation while unknown PUT outcomes retain reconciliation evidence
 *   - audio attachment preserves reconciliation evidence when confirmation is unavailable
 *   - audio replacement keeps a committed attachment when the final database response is uncertain
 *   - audio replacement does not clear cleanup evidence after a delete fence wins
 *   - known S3 versions survive detached cleanup failure and retries delete those exact versions
 *   - failed promotion retains the uploaded exact version when its cleanup fails
 *   - replacement stops before PUT when analysis attached newer exact-version cleanup evidence after the initial read
 *   - Soundtrack deletion removes every motion preview object by exact version before metadata finalization
 *   - Soundtrack deletion waits for a live preview upload and resolves an expired unknown outcome by HEAD
 *   - media replacement retires a preview made for the replaced source without changing the upload result
 * @end-catalog */

import assert from 'node:assert/strict';
import test from 'node:test';
import {
    AudioUploadDependencies,
    AudioTrackDeletionDependencies,
    deleteAudioObjectAndTrack,
    isAudioObjectKeyForTrack,
    uploadAudioObject,
    uploadMediaObject
} from '../../src/services/audio/audioStorageService';

const trackId = '507f1f77bcf86cd799439011';
const replacementId = '507f1f77bcf86cd799439012';
const stalePendingId = '507f1f77bcf86cd799439013';
const nextReplacementId = '507f1f77bcf86cd799439014';
const originalKey = trackId;
const replacementKey = `audio/${trackId}/${replacementId}`;
const stalePendingKey = `audio/${trackId}/${stalePendingId}`;
const nextReplacementKey = `audio/${trackId}/${nextReplacementId}`;

/** Creates deterministic deletion boundaries while preserving production call order. */
const deletionDependencies = (
    calls: string[],
    updates: Array<Record<string, unknown>>
    ): AudioTrackDeletionDependencies => ({
    findTrack: async () => ({
        coverArtId: 'cover-art-id',
        s3Key: replacementKey
    }),
    beginDeletion: async (_audioTrackId, _expected, update) => {
        calls.push(`update:${String(update.uploadStatus)}`);
        updates.push(update);
        return { matchedCount: 1 };
    },
    updateTrackWhere: async (_audioTrackId, _expected, update) => {
        calls.push(`update:${String(update.uploadStatus ?? update.referenceCleanupStatus)}`);
        updates.push(update);
        return { matchedCount: 1 };
    },
    deleteAudioObject: async s3Key => { calls.push(`delete-audio-object:${s3Key}`); },
    prepareTrackCoverArtDeletion: async () => {
        calls.push('prepare-cover-art-deletion');
        return true;
    },
    finalizeTrackCoverArtDeletion: async () => { calls.push('finalize-cover-art-deletion'); },
    cleanupReferences: async () => { calls.push('cleanup-references'); },
    deleteTrack: async () => {
        calls.push('delete-track');
        return { deletedCount: 1 };
    }
});

test('Soundtrack deletion retains metadata until storage and reference cleanup finish', async () => {
    const calls: string[] = [];
    const updates: Array<Record<string, unknown>> = [];

    await deleteAudioObjectAndTrack(
        trackId,
        deletionDependencies(calls, updates)
    );

    assert.deepEqual(calls, [
        'update:deleting',
        'prepare-cover-art-deletion',
        `delete-audio-object:${replacementKey}`,
        'cleanup-references',
        'update:complete',
        'delete-track',
        'finalize-cover-art-deletion'
    ]);
    assert.equal(updates[0].referenceCleanupStatus, 'pending');
    assert.equal(updates[1].referenceCleanupStatus, 'complete');
});

