test('audio object keys bind legacy and versioned storage to one Soundtrack identity', () => {
    assert.equal(isAudioObjectKeyForTrack(originalKey, trackId), true);
    assert.equal(isAudioObjectKeyForTrack(replacementKey, trackId), true);
    assert.equal(isAudioObjectKeyForTrack('not-an-id', 'not-an-id'), false);
    assert.equal(isAudioObjectKeyForTrack('507f1f77bcf86cd799439099', trackId), false);
    assert.equal(
        isAudioObjectKeyForTrack('audio/507f1f77bcf86cd799439099/507f1f77bcf86cd799439012', trackId),
        false
    );
});

const uploadFile = {
    fieldname: 'audioFile',
    originalname: 'replacement.mp3',
    encoding: '7bit',
    mimetype: 'audio/mpeg',
    size: 3,
    buffer: Buffer.from('new')
} as Express.Multer.File;

const videoUploadFile = {
    fieldname: 'videoFile',
    originalname: 'replacement.mp4',
    encoding: '7bit',
    mimetype: 'video/mp4',
    size: 5,
    buffer: Buffer.from('video')
} as Express.Multer.File;

test('cross-kind replacement keeps the new Video active while failed Audio cleanup remains retryable', async () => {
    const videoKey = `video/${trackId}/${replacementId}`;
    const nextAudioKey = `audio/${trackId}/${nextReplacementId}`;
    let state: any = {
        mediaType: 'audio',
        s3Key: originalKey,
        uploadStatus: 'ready'
    };
    let replacementKeyForCall = videoKey;
    let failOriginalCleanup = true;
    const deletedKeys: string[] = [];
    const dependencies: AudioUploadDependencies = {
        findTrack: async () => ({ ...state }),
        createObjectKey: () => replacementKeyForCall,
        updateTrackWhere: async (_id, expected, update) => {
            const matches = Object.entries(expected).every(([field, value]) => (
                value === null ? state[field] == null : state[field] === value
            ));
            if (!matches) return { matchedCount: 0 };
            state = { ...state, ...update };
            return { matchedCount: 1 };
        },
        putObject: async () => undefined,
        deleteObject: async (key) => {
            deletedKeys.push(key);
            if (key === originalKey && failOriginalCleanup) {
                throw new Error('simulated old Audio cleanup failure');
            }
        }
    };

    const videoResult = await uploadMediaObject(
        trackId,
        videoUploadFile,
        'owner',
        'video',
        undefined,
        dependencies
    );

    assert.equal(videoResult.cleanupPending, true);
    assert.equal(state.mediaType, 'video');
    assert.equal(state.s3Key, videoKey);
    assert.equal(state.storageCleanupS3Key, originalKey);
    assert.equal(state.storageCleanupMediaType, 'audio');
    assert.equal(state.storageCleanupStatus, 'deleteFailed');

    failOriginalCleanup = false;
    replacementKeyForCall = nextAudioKey;
    const audioResult = await uploadMediaObject(
        trackId,
        uploadFile,
        'owner',
        'audio',
        undefined,
        dependencies
    );

    assert.equal(audioResult.cleanupPending, false);
    assert.equal(state.mediaType, 'audio');
    assert.equal(state.s3Key, nextAudioKey);
    assert.equal(state.storageCleanupS3Key, null);
    assert.equal(state.storageCleanupMediaType, null);
    assert.deepEqual(deletedKeys, [originalKey, originalKey, videoKey]);
});

test('audio upload cannot cross a deletion fence', async () => {
    for (const uploadStatus of ['deleting', 'deleteFailed']) {
        const calls: string[] = [];
        const dependencies: AudioUploadDependencies = {
            findTrack: async () => ({ s3Key: originalKey, uploadStatus }),
            createObjectKey: () => replacementKey,
            updateTrackWhere: async () => {
                calls.push('update');
                return { matchedCount: 1 };
            },
            putObject: async () => { calls.push('put'); },
            deleteObject: async () => { calls.push('delete'); }
        };

        await assert.rejects(
            uploadAudioObject(trackId, uploadFile, 'owner', undefined, dependencies),
            /cannot be uploaded while deletion is pending/
        );
        assert.deepEqual(calls, []);
    }
});

test('audio upload retries recorded failed-object cleanup before reserving a replacement', async () => {
    const deletedKeys: string[] = [];
    let state: any = {
        s3Key: replacementKey,
        uploadStatus: 'ready',
        pendingS3Key: stalePendingKey,
        pendingUploadStatus: 'failed',
        storageCleanupS3Key: originalKey,
        storageCleanupStatus: 'deleteFailed'
    };
    const dependencies: AudioUploadDependencies = {
        findTrack: async () => ({ ...state }),
        createObjectKey: () => nextReplacementKey,
        updateTrackWhere: async (_id, expected, update) => {
            const matches = Object.entries(expected).every(([field, value]) => {
                return value === null ? state[field] == null : state[field] === value;
            });
            if (!matches) return { matchedCount: 0 };
            state = { ...state, ...update };
            return { matchedCount: 1 };
        },
        putObject: async () => undefined,
        deleteObject: async key => { deletedKeys.push(key); }
    };

    const result = await uploadAudioObject(trackId, uploadFile, 'owner', undefined, dependencies);

    assert.equal(result.cleanupPending, false);
    assert.equal(state.s3Key, nextReplacementKey);
    assert.equal(state.pendingS3Key, null);
    assert.equal(state.storageCleanupS3Key, null);
    assert.deepEqual(deletedKeys, [stalePendingKey, originalKey, replacementKey]);
});

test('audio replacement uploads a versioned key, attaches it, then deletes the previous object', async () => {
    const calls: string[] = [];
    let state: any = { s3Key: originalKey, uploadStatus: 'ready' };
    const dependencies: AudioUploadDependencies = {
        findTrack: async () => ({ ...state }),
        createObjectKey: () => replacementKey,
        updateTrackWhere: async (_id, expected, update) => {
            const matches = Object.entries(expected).every(([field, value]) => {
                return value === null ? state[field] == null : state[field] === value;
            });
            if (!matches) return { matchedCount: 0 };
            calls.push(`update:${String(update.pendingUploadStatus ?? update.uploadStatus ?? update.storageCleanupStatus)}`);
            state = { ...state, ...update };
            return { matchedCount: 1 };
        },
        putObject: async key => { calls.push(`put:${key}`); },
        deleteObject: async key => { calls.push(`delete:${key}`); }
    };

    const result = await uploadAudioObject(trackId, uploadFile, 'owner', undefined, dependencies);

    assert.equal(result.cleanupPending, false);
    assert.equal(state.s3Key, replacementKey);
    assert.equal(state.uploadStatus, 'ready');
    assert.deepEqual(calls, [
        'update:pending',
        `put:${replacementKey}`,
        'update:undefined',
        'update:ready',
        `delete:${originalKey}`,
        'update:null'
    ]);
});

test('audio replacement checks final attachment and removes an unattached uploaded object', async () => {
    const deletedKeys: string[] = [];
    let state: any = { s3Key: originalKey, uploadStatus: 'ready' };
    let updateCount = 0;
    const dependencies: AudioUploadDependencies = {
        findTrack: async () => ({ ...state }),
        createObjectKey: () => replacementKey,
        updateTrackWhere: async (_id, expected, update) => {
            updateCount += 1;
            if (updateCount === 1) {
                state = { ...state, ...update };
                return { matchedCount: 1 };
            }
            if (update.uploadStatus === 'ready') return { matchedCount: 0 };
            state = { ...state, ...update };
            return { matchedCount: 1 };
        },
        putObject: async () => undefined,
        deleteObject: async key => { deletedKeys.push(key); }
    };

    await assert.rejects(
        uploadAudioObject(trackId, uploadFile, 'owner', undefined, dependencies),
        /could not be finalized/
    );
    assert.deepEqual(deletedKeys, [replacementKey]);
    assert.equal(state.s3Key, originalKey);
});

test('definite upload rejection releases its reservation while unknown PUT outcomes retain reconciliation evidence', async () => {
    for (const outcomeUnknown of [false, true]) {
        let state: any = { s3Key: originalKey, uploadStatus: 'ready' };
        const dependencies: AudioUploadDependencies = {
            findTrack: async () => ({ ...state }),
            createObjectKey: () => replacementKey,
            updateTrackWhere: async (_id, expected, update) => {
                const matches = Object.entries(expected).every(([field, value]) =>
                    value === null ? state[field] == null : state[field] === value
                );
                if (!matches) return { matchedCount: 0 };
                state = { ...state, ...update };
                return { matchedCount: 1 };
            },
            putObject: async () => { throw outcomeUnknown ? new Error('simulated network failure') :
                Object.assign(new Error('simulated rejected upload'), { $metadata: { httpStatusCode: 403 } }); },
            deleteObject: async () => { assert.fail('Key-only deletion cannot prove an unknown object version was removed.'); }
        };

        await assert.rejects(
            uploadAudioObject(trackId, uploadFile, 'owner', undefined, dependencies),
            (error: any) => error?.code === (outcomeUnknown ? 'audio_upload_outcome_unknown' : 'audio_upload_failed')
                && error?.cleanupPending === outcomeUnknown
        );
        assert.equal(state.pendingUploadOutcomeUnknown, outcomeUnknown);
        assert.equal(state.pendingS3Key, outcomeUnknown ? replacementKey : null);
        if (outcomeUnknown) {
            await assert.rejects(uploadAudioObject(trackId, uploadFile, 'owner', undefined, dependencies),
                (error: any) => error?.code === 'audio_upload_outcome_unknown');
            await assert.rejects(deleteAudioObjectAndTrack(trackId, { findTrack: async () => state }),
                (error: any) => error?.code === 'audio_upload_outcome_unknown');
        }
    }
});

test('audio attachment preserves reconciliation evidence when confirmation is unavailable', async () => {
    let state: any = { s3Key: originalKey, uploadStatus: 'ready' };
    let updateCount = 0;
    const dependencies: AudioUploadDependencies = {
        findTrack: async () => {
            if (updateCount >= 3) throw new Error('confirmation unavailable');
            return { ...state };
        },
        createObjectKey: () => replacementKey,
        updateTrackWhere: async (_id, _expected, update) => {
            updateCount += 1;
            if (update.uploadStatus === 'ready') throw new Error('database response lost');
            state = { ...state, ...update };
            return { matchedCount: 1 };
        },
        putObject: async () => undefined,
        deleteObject: async () => undefined
    };

    await assert.rejects(
        uploadAudioObject(trackId, uploadFile, 'owner', undefined, dependencies),
        (error: any) => error?.code === 'audio_upload_outcome_unknown'
            && error?.cleanupPending === true
            && error?.outcomeUnknown === true
    );
    assert.equal(state.pendingS3Key, replacementKey);
});

