test('known S3 versions survive detached cleanup failure and retries delete those exact versions', async () => {
    let state: any = { s3Key: originalKey, uploadStatus: 'ready',
        mediaRepresentation: { objectKey: originalKey, versionId: 'old-version' } };
    const deletions: Array<[string, string | null | undefined]> = [];
    let failOldCleanup = true;
    const dependencies: AudioUploadDependencies = {
        findTrack: async () => ({ ...state }), createObjectKey: () => replacementKey,
        updateTrackWhere: async (_id, _expected, update) => { state = { ...state, ...update }; return { matchedCount: 1 }; },
        putObject: async () => ({ ETag: '"new-bytes"', VersionId: 'new-version' }),
        deleteObject: async (key, versionId) => {
            deletions.push([key, versionId]);
            if (key === originalKey && failOldCleanup) throw new Error('Unavailable old version.');
        }
    };
    const first = await uploadAudioObject(trackId, uploadFile, 'owner', undefined, dependencies);
    assert.equal(first.cleanupPending, true);
    assert.equal(state.mediaRepresentation.versionId, 'new-version');
    assert.equal(state.storageCleanupS3VersionId, 'old-version');
    assert.equal(state.pendingS3VersionId, null);
    failOldCleanup = false;
    dependencies.createObjectKey = () => nextReplacementKey;
    dependencies.putObject = async () => ({ ETag: '"third-bytes"', VersionId: 'third-version' });
    await uploadAudioObject(trackId, uploadFile, 'owner', undefined, dependencies);
    assert.deepEqual(deletions, [[originalKey, 'old-version'], [originalKey, 'old-version'], [replacementKey, 'new-version']]);
    assert.equal(state.storageCleanupS3VersionId, null);
});

test('failed promotion retains the uploaded exact version when its cleanup fails', async () => {
    let state: any = { s3Key: originalKey, uploadStatus: 'ready' };
    const versions: Array<string | null | undefined> = [];
    const dependencies: AudioUploadDependencies = {
        findTrack: async () => ({ ...state }), createObjectKey: () => replacementKey,
        updateTrackWhere: async (_id, _expected, update) => {
            if (update.uploadStatus === 'ready') throw new Error('Promotion failed.');
            state = { ...state, ...update }; return { matchedCount: 1 };
        },
        putObject: async () => ({ ETag: '"pending-bytes"', VersionId: 'pending-version' }),
        deleteObject: async (_key, versionId) => { versions.push(versionId); throw new Error('Cleanup failed.'); }
    };
    await assert.rejects(uploadAudioObject(trackId, uploadFile, 'owner', undefined, dependencies));
    assert.deepEqual(versions, ['pending-version']);
    assert.equal(state.pendingS3Key, replacementKey);
    assert.equal(state.pendingS3VersionId, 'pending-version');
    assert.equal(state.pendingUploadOutcomeUnknown, false);
    assert.equal(state.s3Key, originalKey);
});


test('replacement stops before PUT when analysis attached newer exact-version cleanup evidence after the initial read', async () => {
    let state: any = { s3Key: originalKey, uploadStatus: 'ready' };
    const evidence = { revision: `mr_${'1'.repeat(32)}`, objectKey: originalKey, versionId: 'discovered-version' };
    const dependencies: AudioUploadDependencies = {
        findTrack: async () => {
            const observed = { ...state };
            state = { ...state, mediaRepresentation: evidence };
            return observed;
        },
        createObjectKey: () => replacementKey,
        updateTrackWhere: async (_id, expected) => {
            assert.equal(expected.mediaRepresentation, null);
            return { matchedCount: 0 };
        },
        putObject: async () => { assert.fail('must not upload after losing cleanup evidence fence'); },
        deleteObject: async () => { assert.fail('must not delete an unversioned old object'); }
    };
    await assert.rejects(uploadAudioObject(trackId, uploadFile, 'owner', undefined, dependencies));
    assert.deepEqual(state.mediaRepresentation, evidence);
});

const previewKey = (id: string) => `motion-preview/${trackId}/${id}`;

test('Soundtrack deletion removes every motion preview object by exact version before metadata finalization', async () => {
    const calls: string[] = [];
    const updates: Array<Record<string, unknown>> = [];
    const dependencies = deletionDependencies(calls, updates);
    const motionPreview = {
        active: { s3Key: previewKey(stalePendingId), versionId: 'active-version', status: 'ready' },
        pending: null,
        cleanup: { s3Key: previewKey(nextReplacementId), versionId: 'cleanup-version', status: 'deleteFailed' },
        revision: 4
    };
    const fences: Array<Record<string, unknown>> = [];
    dependencies.findTrack = async () => ({ coverArtId: 'cover-art-id', s3Key: replacementKey, motionPreview });
    dependencies.beginDeletion = async (_id, expected, update) => {
        fences.push(expected);
        calls.push(`update:${String(update.uploadStatus)}`);
        return { matchedCount: 1 };
    };
    dependencies.deleteAudioObject = async (key, versionId) => {
        calls.push(`delete-audio-object:${key}${versionId ? `@${versionId}` : ''}`);
    };

    await deleteAudioObjectAndTrack(trackId, dependencies);

    // Any concurrent preview write changes this embedded record, so the fence would miss.
    assert.equal(fences[0].motionPreview, motionPreview);
    assert.deepEqual(calls.slice(0, 5), [
        'update:deleting',
        'prepare-cover-art-deletion',
        `delete-audio-object:${replacementKey}`,
        `delete-audio-object:${previewKey(stalePendingId)}@active-version`,
        `delete-audio-object:${previewKey(nextReplacementId)}@cleanup-version`
    ]);
});

test('Soundtrack deletion waits for a live preview upload and resolves an expired unknown outcome by HEAD', async () => {
    const pendingKey = previewKey(stalePendingId);
    const trackWith = (pending: Record<string, unknown>) => async () => ({
        coverArtId: 'cover-art-id', s3Key: replacementKey,
        motionPreview: { active: null, cleanup: null, revision: 1, pending: {
            s3Key: pendingKey, versionId: null, outcomeUnknown: true, ...pending
        } }
    });
    const expired = { status: 'failed', leaseUntil: new Date(Date.now() - 60_000) };
    const run = async (
        pending: Record<string, unknown>,
        head: AudioTrackDeletionDependencies['headMotionPreviewObject'],
        id = trackId
    ) => {
        const calls: string[] = [];
        const dependencies = deletionDependencies(calls, []);
        dependencies.findTrack = trackWith(pending);
        dependencies.headMotionPreviewObject = head;
        dependencies.deleteAudioObject = async (key, versionId) => {
            calls.push(`delete-audio-object:${key}${versionId ? `@${versionId}` : ''}`);
        };
        return { calls, deletion: deleteAudioObjectAndTrack(id, dependencies) };
    };

    const live = await run({ status: 'uploading', leaseUntil: new Date(Date.now() + 60_000) }, async () => {
        assert.fail('a live upload is never resolved by HEAD');
    });
    await assert.rejects(live.deletion, (error: any) => error?.statusCode === 409);
    assert.deepEqual(live.calls, []);

    // Resolution never consults the preview rollout flag, so a disabled rollout cannot block deletion.
    const previous = process.env.FINITUDE_MOTION_PREVIEWS_ENABLED;
    process.env.FINITUDE_MOTION_PREVIEWS_ENABLED = 'false';
    try {
        const landed = await run(expired, async (key) => {
            assert.equal(key, pendingKey);
            return { VersionId: 'landed-version', Metadata: { trackid: trackId } };
        });
        await landed.deletion;
        assert.ok(landed.calls.includes(`delete-audio-object:${pendingKey}@landed-version`));
        assert.ok(landed.calls.includes('delete-track'));

        // Object metadata names the lowercase id, whatever case the deletion request used.
        const uppercase = await run(expired, async () => ({ VersionId: 'landed-version', Metadata: { trackid: trackId } }), trackId.toUpperCase());
        await uppercase.deletion;
        assert.ok(uppercase.calls.includes(`delete-audio-object:${pendingKey}@landed-version`));

        const absent = await run(expired, async () => null);
        await absent.deletion;
        assert.equal(absent.calls.some((call) => call.includes(pendingKey)), false);
        assert.ok(absent.calls.includes('delete-track'));
    } finally {
        if (previous === undefined) delete process.env.FINITUDE_MOTION_PREVIEWS_ENABLED;
        else process.env.FINITUDE_MOTION_PREVIEWS_ENABLED = previous;
    }

    for (const head of [
        async () => ({ VersionId: 'foreign-version', Metadata: { trackid: 'someone-else' } }),
        async () => { throw new Error('S3 unavailable'); }
    ]) {
        const refused = await run(expired, head);
        await assert.rejects(refused.deletion, (error: any) => error?.statusCode === 503);
        assert.deepEqual(refused.calls, []);
    }
});

test('media replacement retires a preview made for the replaced source without changing the upload result', async () => {
    let state: any = { s3Key: originalKey, uploadStatus: 'ready' };
    const retired: string[] = [];
    const dependencies = (retire: (id: string) => Promise<unknown>): AudioUploadDependencies => ({
        findTrack: async () => ({ ...state }),
        createObjectKey: () => replacementKey,
        updateTrackWhere: async (_id, expected, update) => {
            const matches = Object.entries(expected).every(([field, value]) => (
                value === null ? state[field] == null : state[field] === value
            ));
            if (!matches) return { matchedCount: 0 };
            state = { ...state, ...update };
            return { matchedCount: 1 };
        },
        putObject: async () => undefined,
        deleteObject: async () => undefined,
        retireMotionPreview: retire
    });

    const result = await uploadAudioObject(trackId, uploadFile, 'owner', undefined, dependencies(async (id) => {
        retired.push(`${id}:${state.s3Key}`);
    }));
    assert.equal(result.s3Key, replacementKey);
    // Retirement runs only after the new source is active.
    assert.deepEqual(retired, [`${trackId}:${replacementKey}`]);

    state = { s3Key: originalKey, uploadStatus: 'ready' };
    const failedRetirement = await uploadAudioObject(trackId, uploadFile, 'owner', undefined, dependencies(async () => {
        throw new Error('preview cleanup unavailable');
    }));
    assert.equal(failedRetirement.s3Key, replacementKey);
    assert.equal(failedRetirement.cleanupPending, false);
});
